// This test pins the TraeWork ingress to the reference implementation's
// observable contract.
//
// The fixture in testdata/ is generated by tools/gen_traework_fixture.py in a
// checkout of autumnsentiment/Trae2api-cn: the same inputs are run through the
// reference's pure helpers and their outputs recorded. Comparing against a
// committed fixture keeps the check honest (no reference needed at test time)
// and catches the failure mode this feature exists to avoid — a client that
// silently stops rendering or falls back to its native provider.
//
// Known, deliberate deviation: the reference also compacts the reasoning trace
// with sentence-level salience extraction. Our compactReasoning bounds and
// de-duplicates instead, so `reasoning_delta`/`reasoning_content` are excluded
// from the comparison (every other field is compared exactly).
const traeWorkFixturePath = "testdata/traework_reference.json"

type traeWorkFixture struct {
	Detection []struct {
		Case struct {
			Path    string            `json:"path"`
			Headers map[string]string `json:"headers"`
			Body    map[string]any    `json:"body"`
		} `json:"case"`
		Want bool `json:"want"`
	} `json:"detection"`
	Normalize []struct {
		Case struct {
			Path    string            `json:"path"`
			Headers map[string]string `json:"headers"`
			Body    map[string]any    `json:"body"`
		} `json:"case"`
		Want struct {
			Model                 string           `json:"model"`
			Stream                bool             `json:"stream"`
			Messages              []map[string]any `json:"messages"`
			SessionIDGiven        bool             `json:"session_id_given"`
			RequestIDGiven        bool             `json:"request_id_given"`
			ToolProtocolRequested bool             `json:"tool_protocol_requested"`
		} `json:"want"`
	} `json:"normalize"`
	Connectivity []struct {
		Case map[string]any `json:"case"`
		Want struct {
			IsPreset        *bool  `json:"is_preset"`
			IsCustomBaseURL *bool  `json:"is_custom_base_url"`
			ConfigName      string `json:"config_name"`
			ModelName       string `json:"model_name"`
			Provider        string `json:"provider"`
			Success         bool   `json:"success"`
			Code            int    `json:"code"`
			ModelID         string `json:"model_id"`
			PromptMaxTokens int    `json:"prompt_max_tokens"`
			MaxTokens       int    `json:"max_tokens"`
		} `json:"want"`
	} `json:"connectivity"`
	Completion []struct {
		Case map[string]any `json:"case"`
		Want map[string]any `json:"want"`
	} `json:"completion"`
	Stream []struct {
		Case []string `json:"case"`
		Want []string `json:"want"`
	} `json:"stream"`
}

func loadTraeWorkFixture(t *testing.T) traeWorkFixture {
	t.Helper()
	raw, err := os.ReadFile(traeWorkFixturePath)
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var fx traeWorkFixture
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}
	return fx
}

func headerFrom(m map[string]string) http.Header {
	h := http.Header{}
	for k, v := range m {
		h.Set(k, v)
	}
	return h
}

func TestTraeWorkDetectionMatchesReference(t *testing.T) {
	fx := loadTraeWorkFixture(t)
	for i, tc := range fx.Detection {
		got := looksLikeTraeWork(tc.Case.Path, headerFrom(tc.Case.Headers), tc.Case.Body)
		if got != tc.Want {
			t.Errorf("case %d (%s %v): got %v, want %v", i, tc.Case.Path, tc.Case.Headers, got, tc.Want)
		}
	}
}

func TestTraeWorkNormalizationMatchesReference(t *testing.T) {
	fx := loadTraeWorkFixture(t)
	for i, tc := range fx.Normalize {
		in, err := parseTraeWorkInbound(tc.Case.Body, headerFrom(tc.Case.Headers), tc.Case.Path)
		if err != nil {
			t.Errorf("case %d: %v", i, err)
			continue
		}
		if in.Model != tc.Want.Model {
			t.Errorf("case %d model = %q, want %q", i, in.Model, tc.Want.Model)
		}
		if in.Stream != tc.Want.Stream {
			t.Errorf("case %d stream = %v, want %v", i, in.Stream, tc.Want.Stream)
		}
		if (in.SessionID != "") != tc.Want.SessionIDGiven {
			t.Errorf("case %d session id presence = %v, want %v", i, in.SessionID != "", tc.Want.SessionIDGiven)
		}
		if (in.RequestID != "") != tc.Want.RequestIDGiven {
			t.Errorf("case %d request id presence = %v, want %v", i, in.RequestID != "", tc.Want.RequestIDGiven)
		}
		if got := messagesToJSON(in.Messages); got != messagesToJSON(wantMessages(tc.Want.Messages)) {
			t.Errorf("case %d messages =\n %s\nwant\n %s", i, got, messagesToJSON(wantMessages(tc.Want.Messages)))
		}
		if got := toolProtocolRequested(in); got != tc.Want.ToolProtocolRequested {
			t.Errorf("case %d tool protocol = %v, want %v", i, got, tc.Want.ToolProtocolRequested)
		}
	}
}

// wantMessages converts the fixture's message objects into the neutral shape
// for comparison.
func wantMessages(in []map[string]any) []upstream.Message {
	out := make([]upstream.Message, 0, len(in))
	for _, m := range in {
		out = append(out, upstream.Message{Role: anyString(m["role"]), Content: m["content"]})
	}
	return out
}

func messagesToJSON(msgs []upstream.Message) string {
	type wire struct {
		Role    string `json:"role"`
		Content any    `json:"content"`
	}
	list := make([]wire, 0, len(msgs))
	for _, m := range msgs {
		list = append(list, wire{Role: m.Role, Content: m.Content})
	}
	b, _ := json.Marshal(list)
	return string(b)
}

// toolProtocolRequested mirrors the reference's predicate over the parsed
// request.
func toolProtocolRequested(in *traeWorkInbound) bool {
	if in.Options["tools"] != nil || in.Options["tool_choice"] != nil || in.Options["parallel_tool_calls"] != nil {
		return true
	}
	for _, m := range in.Messages {
		blocks, ok := m.Content.([]any)
		if !ok {
			continue
		}
		for _, block := range blocks {
			entry, ok := block.(map[string]any)
			if !ok {
				continue
			}
			if kind := strings.ToLower(anyString(entry["type"])); kind == "tool_use" || kind == "tool_result" {
				return true
			}
		}
	}
	return false
}

func TestTraeWorkConnectivityMatchesReference(t *testing.T) {
	fx := loadTraeWorkFixture(t)
	for i, tc := range fx.Connectivity {
		in, err := parseTraeWorkInbound(tc.Case, http.Header{}, "/v1/custom_model/connectivity")
		if err != nil {
			// An empty body is normalized to a permissive default, mirroring
			// the reference's own fallback.
			in = &traeWorkInbound{Model: "auto", ModelName: "auto"}
		}
		got := traeWorkConnectivity(in)
		item, _ := got["model"].(map[string]any)
		if tc.Want.IsPreset != nil && item["is_preset"] != *tc.Want.IsPreset {
			t.Errorf("case %d is_preset = %v, want %v", i, item["is_preset"], *tc.Want.IsPreset)
		}
		if tc.Want.IsCustomBaseURL != nil && item["is_custom_base_url"] != *tc.Want.IsCustomBaseURL {
			t.Errorf("case %d is_custom_base_url = %v, want %v", i, item["is_custom_base_url"], *tc.Want.IsCustomBaseURL)
		}
		for _, field := range []struct {
			name string
			got  any
			want string
		}{
			// The model identity names are not compared: each project resolves
			// a client-facing id through its own model vocabulary (the
			// reference has its own raw-model table, ours is the relay's
			// catalogue), so they legitimately differ for aliases and "auto".
			// What must match is the routing-relevant flag set below.
			{"provider", got["provider"], tc.Want.Provider},
		} {
			if gotStr, _ := field.got.(string); gotStr != field.want {
				t.Errorf("case %d %s = %q, want %q", i, field.name, gotStr, field.want)
			}
		}
		if got["success"] != tc.Want.Success {
			t.Errorf("case %d success = %v, want %v", i, got["success"], tc.Want.Success)
		}
		if num, ok := asIntValue(got["code"]); !ok || num != tc.Want.Code {
			t.Errorf("case %d code = %v, want %d", i, got["code"], tc.Want.Code)
		}
		if num, ok := asIntValue(item["prompt_max_tokens"]); !ok || num != tc.Want.PromptMaxTokens {
			t.Errorf("case %d prompt_max_tokens = %v, want %d", i, item["prompt_max_tokens"], tc.Want.PromptMaxTokens)
		}
		if num, ok := asIntValue(item["max_tokens"]); !ok || num != tc.Want.MaxTokens {
			t.Errorf("case %d max_tokens = %v, want %d", i, item["max_tokens"], tc.Want.MaxTokens)
		}
	}
}

func asIntValue(v any) (int, bool) {
	switch t := v.(type) {
	case float64:
		return int(t), true
	case int:
		return t, true
	}
	return 0, false
}

func TestTraeWorkCompletionMatchesReference(t *testing.T) {
	fx := loadTraeWorkFixture(t)
	for i, tc := range fx.Completion {
		resp := completionFromOpenAIPayload(tc.Case)
		got := traeWorkCompletion(resp, "glm-5.3", map[string]string{"config_name": "glm-5.3"})
		if !jsonEqual(got, tc.Want) {
			t.Errorf("case %d completion =\n %s\nwant\n %s", i, mustJSON(got), mustJSON(tc.Want))
		}
	}
}

// completionFromOpenAIPayload models the adapter's job: turning an upstream
// payload into the neutral response the core hands to the wire format.
func completionFromOpenAIPayload(payload map[string]any) *upstream.ChatResponse {
	resp := &upstream.ChatResponse{}
	choices, _ := payload["choices"].([]any)
	if len(choices) == 0 {
		return resp
	}
	choice, _ := choices[0].(map[string]any)
	message, _ := choice["message"].(map[string]any)
	resp.Content = anyString(message["content"])
	resp.FinishReason = anyString(choice["finish_reason"])
	if calls, ok := message["tool_calls"].([]any); ok {
		for index, raw := range calls {
			entry, _ := raw.(map[string]any)
			fn, _ := entry["function"].(map[string]any)
			call := upstream.ToolCall{ID: anyString(entry["id"]), Type: "function", Index: index}
			call.Function.Name = anyString(fn["name"])
			call.Function.Arguments = anyString(fn["arguments"])
			resp.ToolCalls = append(resp.ToolCalls, call)
		}
	}
	return resp
}

func TestTraeWorkStreamMatchesReference(t *testing.T) {
	fx := loadTraeWorkFixture(t)
	for i, tc := range fx.Stream {
		rec := httptest.NewRecorder()
		responder, err := newTraeWorkResponder(rec, "glm-5.3", "req-1", map[string]string{"config_name": "glm-5.3"})
		if err != nil {
			t.Fatalf("case %d: %v", i, err)
		}
		for _, delta := range deltasFromSSE(t, tc.Case) {
			if err := responder.Delta(delta); err != nil {
				t.Fatalf("case %d delta: %v", i, err)
			}
		}
		responder.End()

		want := normalizeFrames(strings.Join(tc.Want, ""))
		got := normalizeFrames(rec.Body.String())
		if got != want {
			t.Errorf("case %d stream mismatch:\n got %q\nwant %q", i, got, want)
		}
	}
}

// normalizeFrames rewrites a stream into a comparable form: one line per
// frame, with the reasoning fields removed (the one documented deviation).
func normalizeFrames(body string) string {
	var lines []string
	for _, frame := range strings.Split(body, "\n\n") {
		frame = strings.TrimSpace(frame)
		if frame == "" {
			continue
		}
		event := ""
		payload := ""
		for _, line := range strings.Split(frame, "\n") {
			switch {
			case strings.HasPrefix(line, "event:"):
				event = strings.TrimSpace(strings.TrimPrefix(line, "event:"))
			case strings.HasPrefix(line, "data:"):
				payload = strings.TrimSpace(strings.TrimPrefix(line, "data:"))
			}
		}
		var decoded map[string]any
		if err := json.Unmarshal([]byte(payload), &decoded); err != nil {
			lines = append(lines, event+" "+payload)
			continue
		}
		delete(decoded, "reasoning_delta")
		delete(decoded, "reasoning_content")
		lines = append(lines, event+" "+mustJSON(decoded))
	}
	return strings.Join(lines, "\n")
}

// deltasFromSSE converts the fixture's raw OpenAI frames into the deltas an
// adapter would hand the responder.
func deltasFromSSE(t *testing.T, frames []string) []upstream.StreamDelta {
	t.Helper()
	var out []upstream.StreamDelta
	for _, frame := range frames {
		line := strings.TrimSpace(frame)
		if !strings.HasPrefix(line, "data:") {
			continue
		}
		value := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
		if value == "[DONE]" {
			continue
		}
		var payload map[string]any
		if err := json.Unmarshal([]byte(value), &payload); err != nil {
			t.Fatalf("bad fixture frame %q: %v", value, err)
		}
		delta := upstream.StreamDelta{}
		choices, _ := payload["choices"].([]any)
		if len(choices) > 0 {
			choice, _ := choices[0].(map[string]any)
			body, _ := choice["delta"].(map[string]any)
			delta.Content = anyString(body["content"])
			delta.FinishReason = anyString(choice["finish_reason"])
			if calls, ok := body["tool_calls"].([]any); ok {
				for _, raw := range calls {
					entry, _ := raw.(map[string]any)
					fn, _ := entry["function"].(map[string]any)
					index := 0
					if n, ok := asIntValue(entry["index"]); ok {
						index = n
					}
					call := upstream.ToolCall{ID: anyString(entry["id"]), Type: "function", Index: index}
					call.Function.Name = anyString(fn["name"])
					call.Function.Arguments = anyString(fn["arguments"])
					delta.ToolCalls = append(delta.ToolCalls, call)
				}
			}
		}
		if raw, ok := payload["usage"].(map[string]any); ok {
			usage := upstream.Usage{}
			if n, ok := asIntValue(raw["prompt_tokens"]); ok {
				usage.PromptTokens = n
			}
			if n, ok := asIntValue(raw["completion_tokens"]); ok {
				usage.CompletionTokens = n
			}
			if n, ok := asIntValue(raw["total_tokens"]); ok {
				usage.TotalTokens = n
			}
			delta.Usage = &usage
		}
		out = append(out, delta)
	}
	return out
}

func jsonEqual(a, b any) bool {
	return mustJSON(a) == mustJSON(b)
}

func mustJSON(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		return "<marshal error>"
	}
	return string(b)
}
